import type { Config } from 'tailwindcss';

/**
 * Every colour is a theme token: `rgb(var(--slate-800) / <alpha-value>)`, so opacity modifiers (bg-slate-900/60) keep working and each
 * component follows the light/dark theme from globals.css (generated by scripts/gen-theme.mjs). No component carries its own theme logic.
 */
const STEPS = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950] as const;
const scale = (name: string) => Object.fromEntries(STEPS.map((s) => [s, `rgb(var(--${name}-${s}) / <alpha-value>)`]));
const token = (name: string) => `rgb(var(--${name}) / <alpha-value>)`;

const config: Config = {
  darkMode: ['class'],
  content: ['./src/pages/**/*.{js,ts,jsx,tsx,mdx}', './src/components/**/*.{js,ts,jsx,tsx,mdx}', './src/app/**/*.{js,ts,jsx,tsx,mdx}'],
  theme: {
    extend: {
      colors: {
        slate: scale('slate'),
        cyan: scale('cyan'),
        blue: scale('blue'),
        emerald: scale('emerald'),
        amber: scale('amber'),
        rose: scale('rose'),
        red: scale('red'),
        purple: scale('purple'),
        orange: scale('orange'),
        white: token('white'),
        black: token('black'),
        // semantic tokens for the shell and shared components
        background: token('background'),
        surface: token('surface'),
        'surface-muted': token('surface-muted'),
        border: token('border-default'),
        card: token('surface'),
        fg: token('text-primary'),
        'fg-muted': token('text-secondary'),
        primary: { DEFAULT: token('primary'), hover: token('primary-hover'), foreground: token('primary-foreground') },
        brand: { bar: token('brand-bar'), red: token('brand-red'), fg: token('brand-fg') },
      },
    },
  },
  plugins: [],
};

export default config;
